import type { Plugin } from 'vite'

/**
 * The seller's request submission is generated by the older wizard transforms.
 * Attach validation after those transforms so earlier string anchors remain intact.
 */
export function pricingRequiredFieldFinalFeedback(): Plugin {
  return {
    name: 'dhole-pricing-required-field-final-feedback',
    enforce: 'pre',
    transform(source, id) {
      if (id.includes('?') || !id.replaceAll('\\', '/').endsWith('/src/modules/pricing/components/PricingAlternativeWizardCrystal.vue')) {
        return null
      }

      const entry = 'async function saveOpenRequest() {'
      const count = source.split(entry).length - 1
      if (count !== 1) return null

      let code = source.replace(entry,
        `${entry}\n  if (!validateRequiredFields()) return`)

      // Preserve the selected Anticipado / Redestino handling after the older
      // request-prefix compatibility transforms have completed.
      code = code.replace(
        "    form.carrierHaulage = false\n    form.validTo = ''",
        "    form.carrierHaulage = false\n    form.portHandlingMode = sellerPortHandlingMode.value\n    form.validTo = ''",
      )

      // The seller must be allowed to click Enviar even when fields are empty.
      // The click then explains the missing fields and highlights them.
      code = code.replace(
        /(<DhButton\b[^>]*?)(:disabled="saving\s*\|\|\s*!canNext")([^>]*?@click="saveOpenRequest")/g,
        '$1:disabled="saving"$3',
      )

      return { code, map: null }
    },
  }
}
